fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Compute the alternating‐sign prefix sum S(k):
    //   S(k) =  k/2   if k is even
    //          -(k+1)/2 if k is odd
    //
    // We do the computation in i16 to avoid any intermediate overflow,
    // then cast back to i8 for the final result.
    fn prefix_sum(k: i16) -> i16 {
        if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    let mut result = Vec::with_capacity(queries.len());
    for (l, r) in queries {
        // Promote to i16 for safe arithmetic
        let l1 = (l as i16) - 1;
        let r1 = r as i16;

        // The sum over [l..=r] is S(r) - S(l-1)
        let sum_i16 = prefix_sum(r1) - prefix_sum(l1);
        result.push(sum_i16 as i8);
    }
    result
}

