        // Sequence a: [-1, +2, -3, +4, -5, +6, ...]
        // Queries and their expected sums:
        let queries = vec![(1, 3), (2, 4), (1, 1), (1, 2), (3, 3)];
        // sums: [-1+2-3 = -2, 2-3+4 = 3, -1, -1+2 = 1, -3]
        let expected = vec![-2, 3, -1, 1, -3];
